<script setup lang="ts">
import {computed,ref,watch,onScopeDispose} from 'vue';import {useRoute} from 'vue-router';import {useI18n} from 'vue-i18n';import {readArticle,type ReaderArticle} from '../api/newsroom-reader';import {safeHref} from '../lib/navigation-links';
const route=useRoute(),{locale}=useI18n(),zh=computed(()=>locale.value==='zh-CN');const article=ref<ReaderArticle|null>(null),loading=ref(false),error=ref(false);let request:AbortController|undefined;
const dateLabel=computed(()=>{const a=article.value;if(!a)return '';if(a.format==='news-brief')return (zh.value?'简报核验：':'Brief checked: ')+a.reviewedDate;return (a.publishedAt?(zh.value?'赛果日期：':'Classification date: '):(zh.value?'索引发现：':'Indexed: '))+(a.publishedAt||a.indexedAt?new Date((a.publishedAt||a.indexedAt)!).toLocaleString(locale.value):'');});
async function load(){request?.abort();request=new AbortController();loading.value=true;error.value=false;article.value=null;try{article.value=await readArticle(String(route.params.id),AbortSignal.any([request.signal,AbortSignal.timeout(15000)]));}catch{error.value=true;}finally{loading.value=false;}}
watch(()=>route.params.id,load,{immediate:true});onScopeDispose(()=>request?.abort());
</script>
<template><article class="newsroom-reader legal-copy"><RouterLink class="button" to="/newsroom">← {{zh?'返回新闻':'Back to news'}}</RouterLink><template v-if="article"><p class="eyebrow">NOBI / {{article.format==='news-brief'?'NEWS BRIEF':article.kind==='original'?'REPORT':'NEWS INDEX'}}</p><h1 tabindex="-1">{{zh?article.titleZh:article.title}}</h1><p class="caption">{{article.author}} · {{article.sourceName}} · {{dateLabel}}</p><p class="notice">{{zh?article.noticeZh:article.noticeEn}}</p><div class="prose"><p v-for="(p,i) in (zh?article.paragraphsZh:article.paragraphsEn)" :key="i">{{p}}</p><section v-for="(section,i) in article.sections" :key="i"><h2>{{zh?section.headingZh:section.headingEn}}</h2><ul><li v-for="(row,j) in section.rows" :key="j">{{zh?row.zh:row.en}}</li></ul></section></div><p v-if="article.backgroundSource" class="caption">{{zh?'补充数据署名：':'Reference data: '}}{{article.backgroundSource}}</p><details v-if="article.originalTitle"><summary>{{zh?'索引原题':'Indexed original headline'}}</summary><p>{{article.originalTitle}}</p></details><footer class="reader-source"><p>{{zh?'资料来源（可选查看）':'Source (optional)'}}</p><a :href="safeHref(article.sourceUrl)" :target="safeHref(article.sourceUrl)?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{article.sourceName}} ↗</a><template v-if="article.licenseUrl"> · <a :href="article.licenseUrl" target="_blank" rel="noopener noreferrer">CC BY 4.0 ↗</a></template></footer></template><p v-else-if="loading" role="status">{{zh?'正在加载新闻…':'Loading article…'}}</p><div v-else-if="error" role="alert"><h1>{{zh?'新闻暂不可用':'Article unavailable'}}</h1><p>{{zh?'该条目可能已超出当前新闻时间范围，或数据源暂时不可用。':'This entry may be outside the current news window or temporarily unavailable.'}}</p><button class="button" @click="load">{{zh?'重试':'Retry'}}</button></div></article></template>
